-- =====================================================================
-- Bubbles-AI — Supabase / Postgres Schema (canonical)
-- =====================================================================
-- Last regenerated: 2026-05-08 (post Phase A drops + Phase B/D RLS hardening
-- + index tuning, via Supabase MCP introspection).
--
-- Apply on a fresh project:
--   psql "<connection-string>" -f db_schema.sql
--
-- Live state on project_ref czjwoqwbwtojlypbzupi was generated by:
--   1. Drop 21 unused tables (zero rows / zero code refs).
--   2. ENABLE RLS on all 37 remaining public.* tables, with policies.
--   3. Pin search_path on user-defined functions.
--   4. Add common-query indexes.
-- =====================================================================


-- ── Extensions ───────────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS postgis;


-- ══════════════════════════════════════════════════════════════════════
-- TABLES (alphabetical)
-- ══════════════════════════════════════════════════════════════════════

CREATE TABLE public.achievements (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  title text NOT NULL,
  description text,
  icon text DEFAULT '🏆'::text,
  category text DEFAULT 'general'::text,
  criteria_type text NOT NULL,
  criteria_value integer NOT NULL,
  xp_reward integer DEFAULT 0,
  created_at timestamptz DEFAULT now(),
  code text UNIQUE,
  tier text
);

CREATE TABLE public.app_feedback (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  rating integer CHECK (rating BETWEEN 1 AND 5),
  feedback_text text,
  app_version text,
  os_info text,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE public.audit_log (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  action text NOT NULL,
  entity_type text,
  entity_id uuid,
  details jsonb,
  ip_address text,
  user_agent text,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE public.coaching_reports (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  session_id uuid,
  report_content jsonb NOT NULL DEFAULT '{}'::jsonb,
  areas_of_improvement text[],
  model_used text,
  user_talk_pct double precision,
  others_talk_pct double precision,
  key_topics text[],
  key_decisions text[],
  action_items text[],
  follow_up_people text[],
  filler_words text[],
  filler_word_count integer DEFAULT 0,
  tone_summary text,
  engagement_trend text,
  suggestions text[],
  strengths text[],
  report_text text,
  generated_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.consultant_logs (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  session_id uuid,
  query text,
  question text,
  response text,
  answer text,
  source_screen text,
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.entities (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  canonical_name text NOT NULL,
  display_name text,
  entity_type text NOT NULL,
  aliases text[],
  description text,
  mention_count integer DEFAULT 0,
  is_archived boolean DEFAULT false,
  last_seen_at timestamptz,
  created_at timestamptz DEFAULT now(),
  UNIQUE (user_id, canonical_name)
);

CREATE TABLE public.entity_attributes (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  entity_id uuid REFERENCES public.entities(id) ON DELETE CASCADE,
  attribute_key text NOT NULL,
  attribute_value text,
  value_type text DEFAULT 'string'::text,
  confidence numeric DEFAULT 1.0,
  source_session_id uuid,
  source_session text,
  updated_at timestamptz DEFAULT now(),
  UNIQUE (entity_id, attribute_key)
);

CREATE TABLE public.entity_relations (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  source_id uuid REFERENCES public.entities(id) ON DELETE CASCADE,
  target_id uuid REFERENCES public.entities(id) ON DELETE CASCADE,
  relation text NOT NULL,
  strength numeric DEFAULT 1.0,
  source_session text,
  updated_at timestamptz,
  created_at timestamptz DEFAULT now(),
  UNIQUE (source_id, target_id, relation)
);

CREATE TABLE public.entity_tags (
  entity_id uuid NOT NULL REFERENCES public.entities(id) ON DELETE CASCADE,
  tag_id uuid NOT NULL,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  PRIMARY KEY (entity_id, tag_id)
);

CREATE TABLE public.events (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  session_id uuid,
  title text NOT NULL,
  description text,
  due_text text,
  start_time timestamptz,
  end_time timestamptz,
  location text,
  is_all_day boolean DEFAULT false,
  is_completed boolean DEFAULT false,
  external_event_id text,
  sync_provider text,
  created_at timestamptz DEFAULT now(),
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE public.feedback (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  session_id uuid,
  log_id uuid,
  consultant_log_id uuid,
  feedback_type text,
  rating integer,
  value integer,
  comment text,
  idempotency_key text UNIQUE,
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.highlights (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  session_id uuid,
  highlight_type text NOT NULL,
  title text,
  body text,
  content text NOT NULL,
  priority integer DEFAULT 1,
  is_resolved boolean DEFAULT false,
  is_dismissed boolean DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.knowledge_graphs (
  user_id uuid NOT NULL PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  graph_data jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz DEFAULT now()
);

CREATE TABLE public.memory (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  session_id uuid,
  content text NOT NULL,
  memory_type text NOT NULL DEFAULT 'general'::text,
  embedding vector(384),
  importance numeric DEFAULT 1.0,
  confidence numeric DEFAULT 1.0,
  source text DEFAULT 'inferred'::text,
  is_pinned boolean DEFAULT false,
  is_archived boolean DEFAULT false,
  created_at timestamptz DEFAULT now(),
  last_accessed_at timestamptz,
  expires_at timestamptz
);

CREATE TABLE public.notification_tokens (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  token text NOT NULL,
  device_type text,
  is_active boolean DEFAULT true,
  added_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now()),
  UNIQUE (user_id, token)
);

CREATE TABLE public.notifications (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  title text NOT NULL,
  body text,
  notif_type text,
  action_url text,
  is_read boolean DEFAULT false,
  read_at timestamptz,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE public.onboarding_progress (
  user_id uuid NOT NULL PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  has_completed_welcome boolean DEFAULT false,
  has_set_voice boolean DEFAULT false,
  has_connected_calendar boolean DEFAULT false,
  has_completed_tutorial boolean DEFAULT false,
