CREATE TABLE public.rewards (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  title text NOT NULL,
  description text,
  icon text DEFAULT '🎁'::text,
  category text DEFAULT 'general'::text,
