  avg_advice_latency_ms numeric,
  total_duration_seconds numeric,
  memories_saved integer DEFAULT 0,
  events_extracted integer DEFAULT 0,
  highlights_created integer DEFAULT 0,
  avg_sentiment_score numeric,
  dominant_sentiment text,
  computed_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.session_logs (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  session_id uuid,
  turn_index integer DEFAULT 0,
  role text NOT NULL,
  content text,
  content_html text,
  model_used text,
  latency_ms integer,
  tokens_used integer,
  finish_reason text,
  has_error boolean DEFAULT false,
  error_message text,
  speaker_label text,
  confidence numeric,
  sentiment_score numeric,
  sentiment_label text,
  created_at timestamptz DEFAULT now()
);

CREATE TABLE public.session_tags (
  session_id uuid NOT NULL,
  tag_id uuid NOT NULL,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  PRIMARY KEY (session_id, tag_id)
);

CREATE TABLE public.sessions (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
