);

CREATE TABLE public.voice_enrollments (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  embedding vector(192) NOT NULL,
  samples_count integer DEFAULT 0,
  model_version text,
  updated_at timestamptz NOT NULL DEFAULT timezone('utc'::text, now())
);

CREATE TABLE public.xp_transactions (
  id uuid NOT NULL DEFAULT uuid_generate_v4() PRIMARY KEY,
  user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE,
  amount integer NOT NULL,
  source_type text NOT NULL,
  source_id text,
  description text,
  created_at timestamptz DEFAULT now()
);


-- ── Cross-table foreign keys (deferred to avoid order issues) ──────────
ALTER TABLE public.coaching_reports
  ADD CONSTRAINT coaching_reports_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.consultant_logs
  ADD CONSTRAINT consultant_logs_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.entity_attributes
  ADD CONSTRAINT entity_attributes_source_session_id_fkey
  FOREIGN KEY (source_session_id) REFERENCES public.sessions(id);

ALTER TABLE public.entity_tags
  ADD CONSTRAINT entity_tags_tag_id_fkey
  FOREIGN KEY (tag_id) REFERENCES public.tags(id) ON DELETE CASCADE;

ALTER TABLE public.events
  ADD CONSTRAINT events_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.feedback
  ADD CONSTRAINT feedback_consultant_log_id_fkey
  FOREIGN KEY (consultant_log_id) REFERENCES public.consultant_logs(id) ON DELETE CASCADE,
  ADD CONSTRAINT feedback_log_id_fkey
  FOREIGN KEY (log_id) REFERENCES public.session_logs(id) ON DELETE CASCADE,
  ADD CONSTRAINT feedback_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.highlights
  ADD CONSTRAINT highlights_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.memory
  ADD CONSTRAINT memory_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.sentiment_logs
  ADD CONSTRAINT sentiment_logs_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.session_analytics
  ADD CONSTRAINT session_analytics_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.session_logs
  ADD CONSTRAINT session_logs_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE;

ALTER TABLE public.session_tags
  ADD CONSTRAINT session_tags_session_id_fkey
  FOREIGN KEY (session_id) REFERENCES public.sessions(id) ON DELETE CASCADE,
  ADD CONSTRAINT session_tags_tag_id_fkey
  FOREIGN KEY (tag_id) REFERENCES public.tags(id) ON DELETE CASCADE;

ALTER TABLE public.sessions
  ADD CONSTRAINT sessions_device_id_fkey
  FOREIGN KEY (device_id) REFERENCES public.user_devices(id);

ALTER TABLE public.tasks
  ADD CONSTRAINT tasks_source_session_id_fkey
  FOREIGN KEY (source_session_id) REFERENCES public.sessions(id);


