-- ══════════════════════════════════════════════════════════════════════

CREATE INDEX IF NOT EXISTS idx_audit_log_user_time
  ON public.audit_log (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_consultant_logs_user
  ON public.consultant_logs (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_entities_canonical
  ON public.entities (user_id, canonical_name);
CREATE INDEX IF NOT EXISTS idx_entities_user
  ON public.entities (user_id, entity_type);
CREATE INDEX IF NOT EXISTS idx_events_session
  ON public.events (session_id);
CREATE INDEX IF NOT EXISTS idx_events_user_time
  ON public.events (user_id, start_time);
CREATE INDEX IF NOT EXISTS idx_feedback_session
  ON public.feedback (session_id);
CREATE INDEX IF NOT EXISTS idx_highlights_user
  ON public.highlights (user_id, is_resolved);
CREATE INDEX IF NOT EXISTS idx_memory_session
  ON public.memory (user_id, session_id);
CREATE INDEX IF NOT EXISTS idx_memory_user_time
  ON public.memory (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_memory_vector
  ON public.memory USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_notifications_unread
  ON public.notifications (user_id, is_read);
CREATE INDEX IF NOT EXISTS idx_notifications_user_time
