  ON public.sentiment_logs (session_id, turn_index);
CREATE INDEX IF NOT EXISTS idx_session_logs_session_turn
  ON public.session_logs (session_id, turn_index);
CREATE INDEX IF NOT EXISTS idx_sessions_mode
  ON public.sessions (user_id, mode);
CREATE INDEX IF NOT EXISTS idx_sessions_user_created
  ON public.sessions (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tasks_user_status
  ON public.tasks (user_id, status, due_date);
CREATE INDEX IF NOT EXISTS idx_user_mistakes_category
  ON public.user_mistakes (user_id, category);
CREATE INDEX IF NOT EXISTS idx_user_mistakes_user_time
  ON public.user_mistakes (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_user_quests_user_date
  ON public.user_quests (user_id, assigned_date);
CREATE INDEX IF NOT EXISTS idx_user_rewards_user
  ON public.user_rewards (user_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_xp_transactions_dedup
  ON public.xp_transactions (user_id, source_type, source_id)
  WHERE source_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_xp_transactions_period
  ON public.xp_transactions (created_at, user_id) WHERE amount > 0;
CREATE INDEX IF NOT EXISTS idx_xp_transactions_user
  ON public.xp_transactions (user_id, source_type, created_at);
CREATE INDEX IF NOT EXISTS idx_xp_transactions_user_time
  ON public.xp_transactions (user_id, created_at DESC);


-- ══════════════════════════════════════════════════════════════════════
-- FUNCTIONS  (search_path pinned to prevent privilege escalation)
-- ══════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.get_user_stats(p_user_id uuid)
RETURNS TABLE (
  total_sessions bigint,
  total_memories bigint,
  total_entities bigint,
  total_highlights bigint,
  open_events bigint
)
LANGUAGE sql STABLE SET search_path = public, pg_temp
AS $$
  SELECT
    (SELECT count(*) FROM public.sessions   WHERE user_id = p_user_id AND deleted_at IS NULL),
    (SELECT count(*) FROM public.memory     WHERE user_id = p_user_id AND is_archived = false),
    (SELECT count(*) FROM public.entities   WHERE user_id = p_user_id AND is_archived = false),
    (SELECT count(*) FROM public.highlights WHERE user_id = p_user_id AND is_dismissed = false AND is_resolved = false),
    (SELECT count(*) FROM public.events     WHERE user_id = p_user_id AND is_completed = false);
$$;

CREATE OR REPLACE FUNCTION public.match_memory(
  query_embedding vector,
  match_threshold double precision,
  match_count integer,
  p_user_id uuid
)
RETURNS TABLE (id uuid, content text, similarity double precision)
LANGUAGE plpgsql SET search_path = public, pg_temp
AS $$
BEGIN
  RETURN QUERY
  SELECT m.id, m.content,
         1 - (m.embedding <=> query_embedding) AS similarity
  FROM public.memory m
  WHERE m.user_id = p_user_id
    AND m.is_archived = false
    AND 1 - (m.embedding <=> query_embedding) > match_threshold
  ORDER BY m.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;

CREATE OR REPLACE FUNCTION public.match_memory_typed(
  query_embedding vector,
  match_threshold double precision,
  match_count integer,
  p_user_id uuid,
  p_memory_type text
)
RETURNS TABLE (id uuid, content text, memory_type text, importance double precision, similarity double precision)
LANGUAGE sql STABLE SET search_path = public, pg_temp
AS $$
  SELECT id, content, memory_type, importance,
         1 - (embedding <=> query_embedding) AS similarity
  FROM public.memory
  WHERE user_id = p_user_id
    AND memory_type = p_memory_type
    AND is_archived = false
    AND (expires_at IS NULL OR expires_at > now())
    AND 1 - (embedding <=> query_embedding) > match_threshold
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;

CREATE OR REPLACE FUNCTION public.match_voice(
  query_embedding vector,
  match_threshold double precision,
  match_count integer
)
RETURNS TABLE (user_id uuid, similarity double precision)
LANGUAGE sql STABLE SET search_path = public, pg_temp
AS $$
  SELECT user_id,
         1 - (embedding <=> query_embedding) AS similarity
  FROM public.voice_enrollments
  WHERE 1 - (embedding <=> query_embedding) > match_threshold
  ORDER BY embedding <=> query_embedding
  LIMIT match_count;
$$;

CREATE OR REPLACE FUNCTION public.top_mistake_categories(p_user uuid, p_days integer)
RETURNS TABLE (category text, n integer)
LANGUAGE sql STABLE SET search_path = public, pg_temp
AS $$
  SELECT category, count(*)::int AS n
  FROM public.user_mistakes
  WHERE user_id = p_user
    AND created_at > now() - (p_days || ' days')::interval
  GROUP BY category
  ORDER BY count(*) DESC
  LIMIT 3;
$$;


