CREATE POLICY "user_achievements_own" ON public.user_achievements
  FOR SELECT TO authenticated USING (auth.uid() = user_id);

ALTER TABLE public.user_mistakes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "user_mistakes_own" ON public.user_mistakes
  FOR SELECT TO authenticated USING (auth.uid() = user_id);

-- Session-scoped policies (joined through sessions.user_id / entities.user_id)
ALTER TABLE public.session_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "session_logs_via_session" ON public.session_logs
  FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.sessions s
                 WHERE s.id = session_logs.session_id AND s.user_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.sessions s
                      WHERE s.id = session_logs.session_id AND s.user_id = auth.uid()));

ALTER TABLE public.entity_attributes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "entity_attributes_via_entity" ON public.entity_attributes
  FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.entities e
                 WHERE e.id = entity_attributes.entity_id AND e.user_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.entities e
                      WHERE e.id = entity_attributes.entity_id AND e.user_id = auth.uid()));

-- Read-only public catalogs (definitions / catalog data only)
ALTER TABLE public.quest_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "quest_definitions_read_all" ON public.quest_definitions
  FOR SELECT TO authenticated USING (true);

ALTER TABLE public.achievements ENABLE ROW LEVEL SECURITY;
CREATE POLICY "achievements_read_all" ON public.achievements
  FOR SELECT TO authenticated USING (true);

ALTER TABLE public.rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "rewards_read_all" ON public.rewards
  FOR SELECT TO authenticated USING (true);


